  { herdrHerdr :: Maybe String
  , herdrPath :: Maybe String
  , herdrHead :: Maybe String
  , herdrStatus :: [String]
  } deriving (Show, Eq)

defaultHerdr :: Herdr
defaultHerdr = Herdr
  { herdrHerdr = Nothing
  , herdrPath = Nothing
  , herdrHead = Nothing
  , herdrStatus = []
  }

decodeHerdr :: Fields -> Either String Herdr
decodeHerdr kv =
  Herdr
    <$> fieldOpt "herdr" kv
    <*> fieldOpt "path" kv
    <*> fieldOpt "head" kv
    <*> fieldList "status" kv

encodeHerdr :: Herdr -> Fields
encodeHerdr r =
  [ ("herdr", encOpt (herdrHerdr r))
  , ("path", encOpt (herdrPath r))
  , ("head", encOpt (herdrHead r))
  , ("status", encList (herdrStatus r))
  ]

herdrHerdrL :: Lens' Herdr (Maybe String)
herdrHerdrL k r = (\v -> r { herdrHerdr = v }) <$> k (herdrHerdr r)
{-# INLINE herdrHerdrL #-}

herdrPathL :: Lens' Herdr (Maybe String)
herdrPathL k r = (\v -> r { herdrPath = v }) <$> k (herdrPath r)
{-# INLINE herdrPathL #-}

herdrHeadL :: Lens' Herdr (Maybe String)
herdrHeadL k r = (\v -> r { herdrHead = v }) <$> k (herdrHead r)
{-# INLINE herdrHeadL #-}

herdrStatusL :: Lens' Herdr ([String])
herdrStatusL k r = (\v -> r { herdrStatus = v }) <$> k (herdrStatus r)
{-# INLINE herdrStatusL #-}

